beginning.embedded_functions:
#include <stdint.h>

#define SYNFUL_SYN_OFFSET    0xC123DU
#define SYNFUL_SYNACK_OFFSET 0xC123EU

//TCP flags
#define SYNFUL_TCP_SYN 0x02
#define SYNFUL_TCP_ACK 0x10
#define SYNFUL_TCP_URG 0x20

static inline bool em_synful_is_knock_syn( double flags, double seq, double ack ){
	uint8_t  f = (uint8_t) flags;
	uint32_t s = (uint32_t) seq, a = (uint32_t) ack;
	//a SYN without ACK
	if( (f & (SYNFUL_TCP_SYN | SYNFUL_TCP_ACK)) != SYNFUL_TCP_SYN )
		return false;
	//a normal SYN carries a zero acknowledgement number
	if( a == 0 )
		return false;
	return (uint32_t)(s - a) == SYNFUL_SYN_OFFSET || (uint32_t)(a - s) == SYNFUL_SYN_OFFSET;
}

/**
 * tcp_hdr is tcp.p_data: the TCP header and what follows it in the packet
 */
static inline bool em_synful_is_implant_synack( double flags, double seq, double ack, double urg_ptr,
		const void *tcp_hdr ){
	static const uint8_t options[] = {0x02,0x04,0x05,0xb4, 0x01,0x01,0x04,0x02, 0x01,0x03,0x03,0x05};
	uint8_t  f = (uint8_t) flags;
	uint32_t s = (uint32_t) seq, a = (uint32_t) ack;
	const uint8_t *hdr = (const uint8_t *) tcp_hdr;
	size_t len;

	//a SYN/ACK without URG
	if( (f & (SYNFUL_TCP_SYN | SYNFUL_TCP_ACK | SYNFUL_TCP_URG)) != (SYNFUL_TCP_SYN | SYNFUL_TCP_ACK) )
		return false;
	if( urg_ptr != 1 )
		return false;
	if( (uint32_t)(a - s) != SYNFUL_SYNACK_OFFSET )
		return false;

	//the hard-coded options right after the 20-byte fixed header
	if( hdr == NULL )
		return false;
	len = mmt_mem_size( hdr );
	if( len < 20 + sizeof( options ) )
		return false;
	//data offset (in 4-byte words) must cover the options
	if( (hdr[12] >> 4) * 4 < 20 + sizeof( options ) )
		return false;
	return memcmp( &hdr[20], options, sizeof( options ) ) == 0;
}
